let best = [grid(PAPER['A4 landscape']), grid(PAPER['A4 portrait'])].reduce((a, c) => (c.cols * c.rows > a.cols * a.rows ? c : a));
const fits = best.cols * best.rows > 0;
let tooBig = false;
